def profile_points(profile, vertices=32):
    profile_type = profile.get('type', 'circle')
    vertices = max(3, int(profile.get('vertices', vertices)))
    if profile_type == 'square':
        half = float(profile.get('radius', profile.get('size', 1.0))) * 0.5
        return [(-half, -half), (half, -half), (half, half), (-half, half)]
    if profile_type == 'octagon':
        return [(math.cos(math.tau * i / 8) * float(profile.get('radius', 1.0)), math.sin(math.tau * i / 8) * float(profile.get('radius', 1.0))) for i in range(8)]
