def taper_scale(taper, t):
    if not taper:
        return 1.0
    points = sorted((float(point['t']), float(point['scale'])) for point in taper)
    if t <= points[0][0]:
        return points[0][1]
    if t >= points[-1][0]:
        return points[-1][1]
    for (t0, s0), (t1, s1) in zip(points, points[1:]):
        if t0 <= t <= t1:
            local = (t - t0) / max(1e-9, t1 - t0)
            return s0 + (s1 - s0) * local
    return points[-1][1]

def path_sweep_samples(path):
    if path.get('type', 'spiral') != 'spiral':
        raise ValueError(f"Unsupported path type: {path.get('type')!r}")
    samples = max(2, int(path.get('samples', 32)))
