    center_y = float(path.get('y', 0.0))
    base_z = float(path.get('z', 0.0))
    start_angle = math.radians(float(path.get('start_angle_deg', 0.0)))
    direction = -1.0 if path.get('direction', 'ccw') == 'cw' else 1.0
    result = []
